package com.hms.waitlist;
import com.hms.appointments.*; import com.hms.doctors.*; import com.hms.tenancy.*; import jakarta.validation.Valid; import java.time.OffsetDateTime; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/public/hospitals/{tenantSlug}/waitlist") public class PublicWaitlistController {private final TenantRepository tenants;private final DoctorRepository doctors;private final PatientRepository patients;private final WaitlistRepository entries;public PublicWaitlistController(TenantRepository t,DoctorRepository d,PatientRepository p,WaitlistRepository e){tenants=t;doctors=d;patients=p;entries=e;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public WaitlistEntry join(@PathVariable String tenantSlug,@Valid @RequestBody CreateWaitlistRequest r){UUID t=tenants.findBySlug(tenantSlug).filter(x->x.getStatus()!=TenantStatus.SUSPENDED&&x.getStatus()!=TenantStatus.CANCELLED&&x.getStatus()!=TenantStatus.EXPIRED).map(Tenant::getId).orElseThrow(()->new IllegalArgumentException("Hospital is not accepting waitlist requests"));doctors.findById(r.doctorId()).filter(d->d.getTenantId().equals(t)&&d.isActive()&&d.isPublicVisible()).orElseThrow(()->new IllegalArgumentException("Doctor is not available"));Patient patient=patients.findFirstByTenantIdAndPhoneOrderByCreatedAtAsc(t,r.phone()).orElseGet(()->patients.save(new Patient(t,new CreateAppointmentRequest(r.fullName(),r.phone(),null,null,r.doctorId(),r.requestedDate().atStartOfDay().atOffset(java.time.ZoneOffset.UTC),r.requestedDate().atStartOfDay().plusMinutes(1).atOffset(java.time.ZoneOffset.UTC),AppointmentSource.PUBLIC,r.reason(),null))));return entries.save(new WaitlistEntry(t,patient.getId(),r.doctorId(),r.requestedDate(),r.reason(),r.priority()));}}
